        crate::daemon::Purpose::HookEnv,
        false,
    )
    .await
    {
        Ok(r) => r,
        Err(e) => {
            // Log error but don't fail the shell hook
            tracing::warn!("failed to resolve secrets: {}", e);
            return Ok(LoadedSecrets {

