            let _ = std::fs::remove_file(&path);
        }
        Ok(())
    }
}

fn should_use_daemon(ctx: &ResolveContext, config: &Config) -> bool {
    #[cfg(not(unix))]
    {
        let _ = ctx;
        let _ = config;
